import React from 'react';
import styles from './OngDashboard.module.css';
import DashboardCard from '../../../components/ui/DashboardCard/DashboardCard';
import { ICONS } from '../../../assets/icons/ICONS';
import logoPlaceholder from '../../../assets/images/logo.png'; // Usa o logo da app como placeholder

// A página agora recebe o 'beneficiary' logado como propriedade
const OngDashboard = ({ beneficiary, onNavigate }) => {
  const cards = [
    { id: 'create_beneficiary', title: 'Cadastrar Beneficiário', icon: ICONS.addbeneficiary },
    { id: 'list_ong_beneficiaries', title: 'Listar Beneficiários', icon: ICONS.list },
    { id: 'acceptance', title: 'Tela de Aceite', icon: ICONS.seal },
    { id: 'help', title: 'Ajuda', icon: ICONS.help },
  ];

  // O nome da ONG agora vem do objeto 'beneficiary' que recebemos no login
  const ongName = beneficiary?.ong_name || 'ONG';
  const ongLogo = beneficiary?.ong_logo_url || logoPlaceholder;

  return (
    <div>
      <div className={styles.header}>
        <img src={ongLogo} alt={`Logótipo da ${ongName}`} className={styles.logo} />
        <h1 className={styles.title}>Painel Administrativo - {ongName}</h1>
      </div>
      <div className={styles.grid}>
        {cards.map(card => (
          <DashboardCard
            key={card.id}
            title={card.title}
            icon={card.icon}
            onClick={() => onNavigate(card.id)}
          />
        ))}
      </div>
    </div>
  );
};

export default OngDashboard;
